use derive_setters :: Setters ; use serde :: Deserialize ; # [doc = " A user-defined command loaded from a Markdown file with YAML frontmatter."] # [doc = ""] # [doc = " Commands are discovered from `.md` files in the forge commands directories"] # [doc = " and made available as slash commands in the UI. The `name` and `description`"] # [doc = " come from YAML frontmatter; the `prompt` is the Markdown body of the file."] # [derive (Debug , Clone , Default , Deserialize , Setters , PartialEq)] # [setters (into , strip_option)] pub struct Command { # [doc = " The command name used to invoke it (e.g. `github-pr-description`)."] # [serde (default)] pub name : String , # [doc = " Short description shown in the command list."] # [serde (default)] pub description : String , # [doc = " The prompt template body (Markdown content after the frontmatter)."] # [serde (default , skip_serializing_if = "Option::is_none")] pub prompt : Option < String > , }